insert into public.legal_provisions (
    version_id, provision_key, sequence, heading_path, heading, label, content
)
select
    '21000000-0000-4000-8000-000000000009', item.chave, item.sequencia, item.caminho, item.titulo, item.rotulo, item.conteudo
from jsonb_to_recordset($dados$[{"chave":"art-1","sequencia":1,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"CAPÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 1º","conteudo":"Esta Lei institui normas gerais para as guardas municipais, disciplinando o § 8º do art. 144 da Constituição Federal."},{"chave":"art-2","sequencia":2,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"CAPÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 2º","conteudo":"Incumbe às guardas municipais, instituições de caráter civil, uniformizadas e armadas conforme previsto em lei, a função de proteção municipal preventiva, ressalvadas as competências da União, dos Estados e do Distrito Federal."},{"chave":"art-3","sequencia":3,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO II — DOS PRINCÍPIOS"],"titulo":"CAPÍTULO II — DOS PRINCÍPIOS","rotulo":"Art. 3º","conteudo":"São princípios mínimos de atuação das guardas municipais:\n\nI - proteção dos direitos humanos fundamentais, do exercício da cidadania e das liberdades públicas;\n\nII - preservação da vida, redução do sofrimento e diminuição das perdas;\n\nIII - patrulhamento preventivo;\n\nIV - compromisso com a evolução social da comunidade; e\n\nV - uso progressivo da força."},{"chave":"art-4","sequencia":4,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO III — DAS COMPETÊNCIAS"],"titulo":"CAPÍTULO III — DAS COMPETÊNCIAS","rotulo":"Art. 4º","conteudo":"É competência geral das guardas municipais a proteção de bens, serviços, logradouros públicos municipais e instalações do Município. (Vide ADPF 995)\n\nParágrafo único. Os bens mencionados no caput abrangem os de uso comum, os de uso especial e os dominiais."},{"chave":"art-5","sequencia":5,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO III — DAS COMPETÊNCIAS"],"titulo":"CAPÍTULO III — DAS COMPETÊNCIAS","rotulo":"Art. 5º","conteudo":"São competências específicas das guardas municipais, respeitadas as competências dos órgãos federais e estaduais:\n\nI - zelar pelos bens, equipamentos e prédios públicos do Município;\n\nII - prevenir e inibir, pela presença e vigilância, bem como coibir, infrações penais ou administrativas e atos infracionais que atentem contra os bens, serviços e instalações municipais;\n\nIII - atuar, preventiva e permanentemente, no território do Município, para a proteção sistêmica da população que utiliza os bens, serviços e instalações municipais;\n\nIV - colaborar, de forma integrada com os órgãos de segurança pública, em ações conjuntas que contribuam com a paz social; Regulamento\n\nV - colaborar com a pacificação de conflitos que seus integrantes presenciarem, atentando para o respeito aos direitos fundamentais das pessoas;\n\nVI - exercer as competências de trânsito que lhes forem conferidas, nas vias e logradouros municipais, nos termos da Lei nº 9.503, de 23 de setembro de 1997 (Código de Trânsito Brasileiro), ou de forma concorrente, mediante convênio celebrado com órgão de trânsito estadual ou municipal;\n\nVII - proteger o patrimônio ecológico, histórico, cultural, arquitetônico e ambiental do Município, inclusive adotando medidas educativas e preventivas;\n\nVIII - cooperar com os demais órgãos de defesa civil em suas atividades;\n\nIX - interagir com a sociedade civil para discussão de soluções de problemas e projetos locais voltados à melhoria das condições de segurança das comunidades;\n\nX - estabelecer parcerias com os órgãos estaduais e da União, ou de Municípios vizinhos, por meio da celebração de convênios ou consórcios, com vistas ao desenvolvimento de ações preventivas integradas;\n\nXI - articular-se com os órgãos municipais de políticas sociais, visando à adoção de ações interdisciplinares de segurança no Município;\n\nXII - integrar-se com os demais órgãos de poder de polícia administrativa, visando a contribuir para a normatização e a fiscalização das posturas e ordenamento urbano municipal;\n\nXIII - garantir o atendimento de ocorrências emergenciais, ou prestá-lo direta e imediatamente quando deparar-se com elas; Regulamento\n\nXIV - encaminhar ao delegado de polícia, diante de flagrante delito, o autor da infração, preservando o local do crime, quando possível e sempre que necessário; Regulamento\n\nXV - contribuir no estudo de impacto na segurança local, conforme plano diretor municipal, por ocasião da construção de empreendimentos de grande porte;\n\nXVI - desenvolver ações de prevenção primária à violência, isoladamente ou em conjunto com os demais órgãos da própria municipalidade, de outros Municípios ou das esferas estadual e federal;\n\nXVII - auxiliar na segurança de grandes eventos e na proteção de autoridades e dignatários; e\n\nXVIII - atuar mediante ações preventivas na segurança escolar, zelando pelo entorno e participando de ações educativas com o corpo discente e docente das unidades de ensino municipal, de forma a colaborar com a implantação da cultura de paz na comunidade local.\n\nParágrafo único. No exercício de suas competências, a guarda municipal poderá colaborar ou atuar conjuntamente com órgãos de segurança pública da União, dos Estados e do Distrito Federal ou de congêneres de Municípios vizinhos e, nas hipóteses previstas nos incisos XIII e XIV deste artigo, diante do comparecimento de órgão descrito nos incisos do caput do art. 144 da Constituição Federal , deverá a guarda municipal prestar todo o apoio à continuidade do atendimento. Regulamento"},{"chave":"art-6","sequencia":6,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO IV — DA CRIAÇÃO"],"titulo":"CAPÍTULO IV — DA CRIAÇÃO","rotulo":"Art. 6º","conteudo":"O Município pode criar, por lei, sua guarda municipal.\n\nParágrafo único. A guarda municipal é subordinada ao chefe do Poder Executivo municipal."},{"chave":"art-7","sequencia":7,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO IV — DA CRIAÇÃO"],"titulo":"CAPÍTULO IV — DA CRIAÇÃO","rotulo":"Art. 7º","conteudo":"As guardas municipais não poderão ter efetivo superior a:\n\nI - 0,4% (quatro décimos por cento) da população, em Municípios com até 50.000 (cinquenta mil) habitantes;\n\nII - 0,3% (três décimos por cento) da população, em Municípios com mais de 50.000 (cinquenta mil) e menos de 500.000 (quinhentos mil) habitantes, desde que o efetivo não seja inferior ao disposto no inciso I;\n\nIII - 0,2% (dois décimos por cento) da população, em Municípios com mais de 500.000 (quinhentos mil) habitantes, desde que o efetivo não seja inferior ao disposto no inciso II.\n\nParágrafo único. Se houver redução da população referida em censo ou estimativa oficial da Fundação Instituto Brasileiro de Geografia e Estatística (IBGE), é garantida a preservação do efetivo existente, o qual deverá ser ajustado à variação populacional, nos termos de lei municipal."},{"chave":"art-8","sequencia":8,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO IV — DA CRIAÇÃO"],"titulo":"CAPÍTULO IV — DA CRIAÇÃO","rotulo":"Art. 8º","conteudo":"Municípios limítrofes podem, mediante consórcio público, utilizar, reciprocamente, os serviços da guarda municipal de maneira compartilhada."},{"chave":"art-9","sequencia":9,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO IV — DA CRIAÇÃO"],"titulo":"CAPÍTULO IV — DA CRIAÇÃO","rotulo":"Art. 9º","conteudo":"A guarda municipal é formada por servidores públicos integrantes de carreira única e plano de cargos e salários, conforme disposto em lei municipal."},{"chave":"art-10","sequencia":10,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO V — DAS EXIGÊNCIAS PARA INVESTIDURA"],"titulo":"CAPÍTULO V — DAS EXIGÊNCIAS PARA INVESTIDURA","rotulo":"Art. 10.","conteudo":"São requisitos básicos para investidura em cargo público na guarda municipal:\n\nI - nacionalidade brasileira;\n\nII - gozo dos direitos políticos;\n\nIII - quitação com as obrigações militares e eleitorais;\n\nIV - nível médio completo de escolaridade;\n\nV - idade mínima de 18 (dezoito) anos;\n\nVI - aptidão física, mental e psicológica; e\n\nVII - idoneidade moral comprovada por investigação social e certidões expedidas perante o Poder Judiciário estadual, federal e distrital.\n\nParágrafo único. Outros requisitos poderão ser estabelecidos em lei municipal."},{"chave":"art-11","sequencia":11,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO VI — DA CAPACITAÇÃO"],"titulo":"CAPÍTULO VI — DA CAPACITAÇÃO","rotulo":"Art. 11.","conteudo":"O exercício das atribuições dos cargos da guarda municipal requer capacitação específica, com matriz curricular compatível com suas atividades.\n\nParágrafo único. Para fins do disposto no caput , poderá ser adaptada a matriz curricular nacional para formação em segurança pública, elaborada pela Secretaria Nacional de Segurança Pública (Senasp) do Ministério da Justiça."},{"chave":"art-12","sequencia":12,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO VI — DA CAPACITAÇÃO"],"titulo":"CAPÍTULO VI — DA CAPACITAÇÃO","rotulo":"Art. 12.","conteudo":"É facultada ao Município a criação de órgão de formação, treinamento e aperfeiçoamento dos integrantes da guarda municipal, tendo como princípios norteadores os mencionados no art. 3º .\n\n§ 1º Os Municípios poderão firmar convênios ou consorciar-se, visando ao atendimento do disposto no caput deste artigo.\n\n§ 2º O Estado poderá, mediante convênio com os Municípios interessados, manter órgão de formação e aperfeiçoamento centralizado, em cujo conselho gestor seja assegurada a participação dos Municípios conveniados.\n\n§ 3º O órgão referido no § 2º não pode ser o mesmo destinado a formação, treinamento ou aperfeiçoamento de forças militares."},{"chave":"art-13","sequencia":13,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO VII — DO CONTROLE"],"titulo":"CAPÍTULO VII — DO CONTROLE","rotulo":"Art. 13.","conteudo":"O funcionamento das guardas municipais será acompanhado por órgãos próprios, permanentes, autônomos e com atribuições de fiscalização, investigação e auditoria, mediante:\n\nI - controle interno, exercido por corregedoria, naquelas com efetivo superior a 50 (cinquenta) servidores da guarda e em todas as que utilizam arma de fogo, para apurar as infrações disciplinares atribuídas aos integrantes de seu quadro; e\n\nII - controle externo, exercido por ouvidoria, independente em relação à direção da respectiva guarda, qualquer que seja o número de servidores da guarda municipal, para receber, examinar e encaminhar reclamações, sugestões, elogios e denúncias acerca da conduta de seus dirigentes e integrantes e das atividades do órgão, propor soluções, oferecer recomendações e informar os resultados aos interessados, garantindo-lhes orientação, informação e resposta.\n\n§ 1º O Poder Executivo municipal poderá criar órgão colegiado para exercer o controle social das atividades de segurança do Município, analisar a alocação e aplicação dos recursos públicos e monitorar os objetivos e metas da política municipal de segurança e, posteriormente, a adequação e eventual necessidade de adaptação das medidas adotadas face aos resultados obtidos.\n\n§ 2º Os corregedores e ouvidores terão mandato cuja perda será decidida pela maioria absoluta da Câmara Municipal, fundada em razão relevante e específica prevista em lei municipal."},{"chave":"art-14","sequencia":14,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO VII — DO CONTROLE"],"titulo":"CAPÍTULO VII — DO CONTROLE","rotulo":"Art. 14.","conteudo":"Para efeito do disposto no inciso I do caput do art. 13, a guarda municipal terá código de conduta próprio, conforme dispuser lei municipal.\n\nParágrafo único. As guardas municipais não podem ficar sujeitas a regulamentos disciplinares de natureza militar."},{"chave":"art-15","sequencia":15,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO VIII — DAS PRERROGATIVAS"],"titulo":"CAPÍTULO VIII — DAS PRERROGATIVAS","rotulo":"Art. 15.","conteudo":"Os cargos em comissão das guardas municipais deverão ser providos por membros efetivos do quadro de carreira do órgão ou entidade.\n\n§ 1º Nos primeiros 4 (quatro) anos de funcionamento, a guarda municipal poderá ser dirigida por profissional estranho a seus quadros, preferencialmente com experiência ou formação na área de segurança ou defesa social, atendido o disposto no caput .\n\n§ 2º Para ocupação dos cargos em todos os níveis da carreira da guarda municipal, deverá ser observado o percentual mínimo para o sexo feminino, definido em lei municipal.\n\n§ 3º Deverá ser garantida a progressão funcional da carreira em todos os níveis."},{"chave":"art-16","sequencia":16,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO VIII — DAS PRERROGATIVAS"],"titulo":"CAPÍTULO VIII — DAS PRERROGATIVAS","rotulo":"Art. 16.","conteudo":"Aos guardas municipais é autorizado o porte de arma de fogo, conforme previsto em lei.\n\nParágrafo único. Suspende-se o direito ao porte de arma de fogo em razão de restrição médica, decisão judicial ou justificativa da adoção da medida pelo respectivo dirigente."},{"chave":"art-17","sequencia":17,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO VIII — DAS PRERROGATIVAS"],"titulo":"CAPÍTULO VIII — DAS PRERROGATIVAS","rotulo":"Art. 17.","conteudo":"A Agência Nacional de Telecomunicações (Anatel) destinará linha telefônica de número 153 e faixa exclusiva de frequência de rádio aos Municípios que possuam guarda municipal."},{"chave":"art-18","sequencia":18,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO VIII — DAS PRERROGATIVAS"],"titulo":"CAPÍTULO VIII — DAS PRERROGATIVAS","rotulo":"Art. 18.","conteudo":"É assegurado ao guarda municipal o recolhimento à cela, isoladamente dos demais presos, quando sujeito à prisão antes de condenação definitiva."},{"chave":"art-19","sequencia":19,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO IX — DAS VEDAÇÕES"],"titulo":"CAPÍTULO IX — DAS VEDAÇÕES","rotulo":"Art. 19.","conteudo":"A estrutura hierárquica da guarda municipal não pode utilizar denominação idêntica à das forças militares, quanto aos postos e graduações, títulos, uniformes, distintivos e condecorações."},{"chave":"art-20","sequencia":20,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO X — DA REPRESENTATIVIDADE"],"titulo":"CAPÍTULO X — DA REPRESENTATIVIDADE","rotulo":"Art. 20.","conteudo":"É reconhecida a representatividade das guardas municipais no Conselho Nacional de Segurança Pública, no Conselho Nacional das Guardas Municipais e, no interesse dos Municípios, no Conselho Nacional de Secretários e Gestores Municipais de Segurança Pública."},{"chave":"art-21","sequencia":21,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO XI — DISPOSIÇÕES DIVERSAS E TRANSITÓRIAS"],"titulo":"CAPÍTULO XI — DISPOSIÇÕES DIVERSAS E TRANSITÓRIAS","rotulo":"Art. 21.","conteudo":"As guardas municipais utilizarão uniforme e equipamentos padronizados, preferencialmente, na cor azul-marinho."},{"chave":"art-22","sequencia":22,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO XI — DISPOSIÇÕES DIVERSAS E TRANSITÓRIAS"],"titulo":"CAPÍTULO XI — DISPOSIÇÕES DIVERSAS E TRANSITÓRIAS","rotulo":"Art. 22.","conteudo":"Aplica-se esta Lei a todas as guardas municipais existentes na data de sua publicação, a cujas disposições devem adaptar-se no prazo de 2 (dois) anos.\n\nParágrafo único. É assegurada a utilização de outras denominações consagradas pelo uso, como guarda civil, guarda civil municipal, guarda metropolitana e guarda civil metropolitana."},{"chave":"art-23","sequencia":23,"caminho":["ESTATUTO GERAL DAS GUARDAS MUNICIPAIS","CAPÍTULO XI — DISPOSIÇÕES DIVERSAS E TRANSITÓRIAS"],"titulo":"CAPÍTULO XI — DISPOSIÇÕES DIVERSAS E TRANSITÓRIAS","rotulo":"Art. 23.","conteudo":"Esta Lei entra em vigor na data de sua publicação."}]$dados$::jsonb)
    as item(chave text, sequencia integer, caminho text[], titulo text, rotulo text, conteudo text);

update public.legal_documents
set current_version_id = '21000000-0000-4000-8000-000000000009'
where id = '20000000-0000-4000-8000-000000000007';

